const { execSync } = require('child_process');

// 1. Get the previous output (Start Task Result)
const prevOutput = items[0].json.stdout;

// 2. Extract Report ID using Regex
const match = prevOutput.match(/<report_id>([^<]+)<\/report_id>/);
const reportId = match ? match[1] : null;

if (!reportId) {
  throw new Error("Could not find Report ID in StartTask output");
}

// 3. Construct Command to get full report
const xml = `<get_reports report_id='${reportId}' format_id='a994b278-1f62-11e1-96ac-406186ea4fc5' details='1'/>`;
const cmd = `/home/node/gvm-env/bin/gvm-cli --gmp-username admin --gmp-password admin123 socket --socketpath /run/gvmd/gvmd.sock --xml "${xml}"`;

try {
  const stdout = execSync(cmd).toString();
  return [{ json: { stdout } }];
} catch (error) {
  throw new Error(error.message);
}

const { exec } = require('child_process');

// exec con timeout de 30s por llamada para evitar que gvm-cli se cuelgue
const execAsync = (cmd) => new Promise((resolve, reject) => {
  exec(cmd, { timeout: 30000 }, (error, stdout) => {
    if (error) reject(error);
    else resolve({ stdout });
  });
});
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const createTaskOutput = $('CreateTask').first().json.stdout;
const taskMatch = createTaskOutput.match(/id="([^"]+)"/);
const taskId = taskMatch ? taskMatch[1] : null;

if (!taskId) {
  throw new Error('No se pudo obtener el Task ID para verificar el estado del escaneo');
}

const MAX_WAIT_MS = 90 * 60 * 1000; // 90 minutos en tiempo de reloj real
const POLL_INTERVAL = 60000; // 60 segundos entre consultas

const startTime = Date.now();

while (Date.now() - startTime < MAX_WAIT_MS) {
  const xml = `<get_tasks task_id='${taskId}'/>`;
  const cmd = `/home/node/gvm-env/bin/gvm-cli --gmp-username admin --gmp-password admin123 socket --socketpath /run/gvmd/gvmd.sock --xml "${xml}"`;

  const { stdout: output } = await execAsync(cmd);
  const statusMatch = output.match(/<status>([^<]+)<\/status>/);
  const status = statusMatch ? statusMatch[1] : 'Unknown';

  if (status === 'Done') {
    return [{ json: { stdout: $('StartTask').first().json.stdout, timed_out: false } }];
  }

  if (status === 'Stopped' || status === 'Interrupted') {
    throw new Error(`El escaneo terminó con estado inesperado: ${status}`);
  }

  await sleep(POLL_INTERVAL);
}

// Timeout alcanzado: retornamos flag en vez de lanzar error para poder notificar por Telegram
return [{ json: { timed_out: true, task_id: taskId } }];

